Section StMva.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis HCF : forall n, as_Cf H n = 0.
  Hypothesis VMV : vmove_stmtA H.

  Variables (ra gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (fc : bv 32) (spz : Z).
  Variables (st1 st2 : Z) (c1 c2 : stateC) (LB0 LBs2 : list block) (A1 A2 A3 A4 A5 A6 B1 B2 B3 B4 B5 B6 : list block).
  Variables (LF : list fframe) (lo B shi : Z) (errv : word) (m0 : mem) (mo0 : Model) (sk0 : as_St H).
  Hypothesis FRZ : frm_zero fc.
  Hypothesis SP16 : spz mod 16 = 0.
  Hypothesis SPR : 2 ^ 45 <= spz - 192 /\ spz <= 2 ^ 47.
  Hypothesis LOH : aceil <= lo /\ lo <= spz - AST_MVA_STACK.
  Hypothesis SHH : spz <= shi /\ shi <= AAPP_HI.
  Hypothesis TPV : tp = Z_to_bv 64 ATP.
  Hypothesis F1 : st_live_frame LF st1.
  Hypothesis F2 : st_live_frame LF st2 \/ (spz <= st2 /\ st2 + ST_SIZE + 64 <= shi).
  Hypothesis FS1 : as_FSB H <= st1 /\ st1 + 240 <= as_FSB H + AFS_SIZE.
  Hypothesis FS2 : (as_FSB H <= st2 /\ st2 + 240 <= as_FSB H + AFS_SIZE) \/ (spz <= st2 /\ st2 + ST_SIZE + 64 <= shi).
  Hypothesis FSBOK : AIMG_TOP <= as_FSB H /\ as_FSB H + AFS_SIZE <= aceil /\ as_FSB H mod 4096 = 0 /\ aapp (as_FSB H) AFS_SIZE.
  Hypothesis ST1C : st1 + 240 <= aceil.
  Hypothesis AP12 : st1 + 240 <= st2 \/ st2 + 240 <= st1.
  Hypothesis AL0 : 0 <= as_AL H sk0.
  Hypothesis SPB : spz <= B.
  Hypothesis TRS : st_mva_tr_ok H.
  Hypothesis PB2 : Permutation LBs2 (B1 ++ B2 ++ B3 ++ B4 ++ B5 ++ B6).
  Hypothesis LA1 : lbl A1 = cb_m1 c1. Hypothesis LA2 : lbl A2 = cb_m2 c1. Hypothesis LA3 : lbl A3 = cb_m3 c1.
  Hypothesis LA4 : lbl A4 = cb_v1 c1. Hypothesis LA5 : lbl A5 = cb_v2 c1. Hypothesis LA6 : lbl A6 = cb_v3 c1.
  Hypothesis LB1 : lbl B1 = cb_m1 c2. Hypothesis LB2 : lbl B2 = cb_m2 c2. Hypothesis LB3 : lbl B3 = cb_m3 c2.
  Hypothesis LB4 : lbl B4 = cb_v1 c2. Hypothesis LB5 : lbl B5 = cb_v2 c2. Hypothesis LB6 : lbl B6 = cb_v3 c2.

  Hypothesis ST1A : st1 mod 8 = 0.
  Hypothesis ST2A : st2 mod 8 = 0.
  Hypothesis VB1 : forall p n, In (p, n) (state_blocks c1) -> n <= 2 ^ 40.
  Hypothesis BAP : forall p n, In (p, n) (state_blocks c1 ++ state_blocks c2) ->
    (p + n <= st1 \/ st1 + 240 <= p) /\ (p + n <= st2 \/ st2 + 240 <= p).

  Definition spf : Z := spz - 96.
  Definition XST : list (Z * Z) := [(st1, st1 + 240); (st2, st2 + 240)].

  Definition INV (s : as_St H) (LBc : list block) (m : mem) (cA cB : stateC) (L : list block) : Prop :=
    mem_inv asegs m /\ stk asegs m lo spz /\ rw_cells asegs m (errno_addr tp) [C4 errv] /\ as_rauxv_ok H m B
    /\ ACONST m /\ as_RFS H LF m /\ stack0 m lo shi /\ as_RHEAP H s LBc m /\ lb_own LBc m
    /\ LbA_HStNT.sto_frame m spf ra s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10
    /\ state_repA LBc m st1 cA /\ state_sh m cA /\ state_repA LBc m st2 cB /\ state_sh m cB
    /\ addressable m st1 240 /\ addressable m st2 240
    /\ Permutation LBc (LB0 ++ L)
    /\ xpres H LB0 spz XST m0 m
    /\ as_AL H s >= as_AL H sk0.

  Definition E3 : Z * Z * list (Z * (Z * Z)) := (0, 0, []).
  Definition E3N : Z * Z * list (Z * (Z * (Z * Z * Z))) := (0, 0, []).
  Definition V0 : Z * Z * Z := (0, 0, 0).
  Definition cA0 : stateC := set_scal c1 c2.
  Definition cA1 : stateC := set_m1 cA0 (st_m1 c2).
  Definition cA2 : stateC := set_m2 cA1 (st_m2 c2).
  Definition cA3 : stateC := set_m3 cA2 (st_m3 c2).
  Definition cA4 : stateC := set_v1 cA3 (st_v1 c2).
  Definition cA5 : stateC := set_v2 cA4 (st_v2 c2).
  Definition cB1 : stateC := set_m1 c2 E3.
  Definition cB2 : stateC := set_m2 cB1 E3N.
  Definition cB3 : stateC := set_m3 cB2 E3.
  Definition cB4 : stateC := set_v1 cB3 V0.
  Definition cB5 : stateC := set_v2 cB4 V0.
  Definition L0 : list block := A1 ++ A2 ++ A3 ++ A4 ++ A5 ++ A6 ++ B1 ++ B2 ++ B3 ++ B4 ++ B5 ++ B6.
  Definition L1 : list block := B1 ++ A2 ++ A3 ++ A4 ++ A5 ++ A6 ++ B2 ++ B3 ++ B4 ++ B5 ++ B6.
  Definition L2 : list block := B1 ++ B2 ++ A3 ++ A4 ++ A5 ++ A6 ++ B3 ++ B4 ++ B5 ++ B6.
  Definition L3 : list block := B1 ++ B2 ++ B3 ++ A4 ++ A5 ++ A6 ++ B4 ++ B5 ++ B6.
  Definition L4 : list block := B1 ++ B2 ++ B3 ++ B4 ++ A5 ++ A6 ++ B5 ++ B6.
  Definition L5 : list block := B1 ++ B2 ++ B3 ++ B4 ++ B5 ++ A6 ++ B6.
  Definition L6 : list block := B1 ++ B2 ++ B3 ++ B4 ++ B5 ++ B6.

  Definition QF : config -> Prop :=
    st_mva_post H ra (Z_to_bv 64 spz) gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 sk0 LB0 LBs2 LF st1 st2 c1 c2 lo B shi m0 mo0.

  Lemma spz_u : bv_unsigned (Z_to_bv 64 spz) = spz.
Proof.
