  Lemma stage_end : forall s LBc m msF mo
      (x1 x5 x6 x7 x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x28 x29 x30 x31 : word) (F : bvmap 5 word),
    as_VIS H s msF = MS (mkR x1 (Z_to_bv 64 spf) gp tp x5 x6 x7 (Z_to_bv 64 st1) x9 x10 x11 x12 x13 x14 x15 x16 x17 x18 x19 x20
                             x21 x22 x23 x24 x25 x26 s11 x28 x29 x30 x31)
                        F (Z_to_bv 64 AST_FIN) fc None m (seg_rom asegs) ->
    as_AKREL H s (mkCfg msF mo) -> as_MPRES H mo0 mo ->
    INV s LBc m (state_moved c1 c2) (state_emptied c2) (B1 ++ B2 ++ B3 ++ B4 ++ B5 ++ B6) ->
