  Lemma INV_step : forall s LBc m cA cB L s' LB' m' LBk o w cA' cB' L',
    INV s LBc m cA cB L ->
    xpres H LBk spf (XW o w) m m' -> 0 <= o -> 0 <= w -> o + w <= 240 ->
    (forall b, In b LB0 -> In b LBk) ->
    mem_inv asegs m' -> stk asegs m' lo spf -> rw_cells asegs m' (errno_addr tp) [C4 errv] -> as_rauxv_ok H m' B ->
    ACONST m' -> as_RFS H LF m' -> stack0 m' lo shi -> as_RHEAP H s' LB' m' -> lb_own LB' m' ->
    as_AL H s' >= as_AL H s ->
    state_repA LB' m' st1 cA' -> state_sh m' cA' -> state_repA LB' m' st2 cB' -> state_sh m' cB' ->
    Permutation LB' (LB0 ++ L') ->
    INV s' LB' m' cA' cB' L'.
Proof.
