  Lemma obj_facts : forall off, 0 <= off -> off + 40 <= 240 -> off mod 8 = 0 ->
    (AIMG_TOP <= st1 + off /\ st1 + off + 40 <= aceil /\ (st1 + off) mod 8 = 0 /\ in_app_mem (st1 + off) (st1 + off + 40))
    /\ (AIMG_TOP <= st2 + off /\ st2 + off + 40 <= 2 ^ 47 /\ (st2 + off) mod 8 = 0 /\ in_app_mem (st2 + off) (st2 + off + 40)
        /\ (st2 + off + 40 <= aceil \/ spf <= st2 + off))
    /\ apart (st1 + off) 40 (st2 + off) 40
    /\ (as_FSB H <= st1 + off /\ st1 + off + 40 <= as_FSB H + AFS_SIZE)
    /\ ((as_FSB H <= st2 + off /\ st2 + off + 40 <= as_FSB H + AFS_SIZE) \/ aceil <= st2 + off)
    /\ afs_write_ok H LF (st1 + off, st1 + off + 40) /\ afs_write_ok H LF (st2 + off, st2 + off + 40)
    /\ aconst_ok (st1 + off, st1 + off + 40) /\ aconst_ok (st2 + off, st2 + off + 40)
    /\ ((exists f, In f LF /\ ff_addr f <= st2 + off /\ st2 + off + 40 <= ff_addr f + fsz (ff_class f))
        \/ (lo + 64 <= st2 + off /\ st2 + off + 104 <= shi)).
Proof.
